class Solution {
  public String abbreviateProduct(int left, int right) {
    long twos = 0, fives = 0;
    double log = 0, comp = 0; // Kahan summation: plain accumulation drifts by ~1e-11
    for (int x = left; x <= right; x++) {
      double y = Math.log10(x) - comp, t = log + y;
      comp = (t - log) - y;
      log = t;
      int v = x;
      while (v % 2 == 0) {
        v /= 2;
        twos++;
      }
      while (v % 5 == 0) {
        v /= 5;
        fives++;
      }
    }
    int zeros = (int) Math.min(twos, fives);
    twos -= zeros;
    fives -= zeros;
    // the product without trailing zeros = stripped factors * leftover twos * leftover fives
    final long MOD = 100000, LIMIT = 10_000_000_000L;
    long suffix = 1, exact = 1;
    boolean small = true;
    for (int x = left; x <= right; x++) {
      int v = x;
      while (v % 2 == 0) v /= 2;
      while (v % 5 == 0) v /= 5;
      suffix = suffix * (v % MOD) % MOD;
      if (small) {
        exact *= v;
        if (exact >= LIMIT) small = false;
      }
    }
    for (long i = 0; i < twos; i++) {
      if (small) {
        exact *= 2;
        if (exact >= LIMIT) small = false;
      }
    }
    for (long i = 0; i < fives; i++) {
      if (small) {
        exact *= 5;
        if (exact >= LIMIT) small = false;
      }
    }
    suffix = suffix * power(2, twos, MOD) % MOD * power(5, fives, MOD) % MOD;
    if (small) return exact + "e" + zeros;
    double digits = log - zeros;
    int prefix = (int) Math.pow(10, digits - Math.floor(digits) + 4);
    return prefix + "..." + String.format("%05d", suffix) + "e" + zeros;
  }

  private long power(long base, long exp, long mod) {
    long result = 1;
    base %= mod;
    while (exp > 0) {
      if ((exp & 1) == 1) result = result * base % mod;
      base = base * base % mod;
      exp >>= 1;
    }
    return result;
  }
}
